export function normalizeMoodleCourseCode(value = '') {
  return String(value || '').trim().toUpperCase().replace(/[-\s]/g, '')
}

export function getCurrentMoodleRoom(courseCode, section) {
  const raw = String(courseCode || '').trim().toUpperCase()
  const normalized = normalizeMoodleCourseCode(raw)
  const key = Object.keys(CURRENT_MOODLE_COURSE_MAP).find(
    (item) => normalizeMoodleCourseCode(item) === normalized
  )
  if (!key) return null
  const room = CURRENT_MOODLE_COURSE_MAP[key]?.sections?.[String(section || '').trim().toUpperCase()]
  return room?.mapped ? room : null
}
